Start-Process "C:\Program Files\Docker\Docker\Docker Desktop.exe"
$deadline = 180
for ($i = 0; $i -lt $deadline; $i += 5) {
    docker info --format '{{.ServerVersion}}' 2>$null | Out-Null
    if ($LASTEXITCODE -eq 0) { "Docker engine ready after ~${i}s"; docker info --format 'server {{.ServerVersion}} / {{.OSType}}'; break }
    Start-Sleep -Seconds 5
}
if ($LASTEXITCODE -ne 0) { "Docker still not ready after ${deadline}s" }

$ready = $false
for ($i = 0; $i -lt 240; $i += 5) {
    $out = docker info --format '{{.ServerVersion}}|{{.OSType}}' 2>&1
    if ($out -notmatch 'error during connect|cannot find') { $ready = $true; "Docker ready after ~${i}s -> $out"; break }
    Start-Sleep -Seconds 5
}
if (-not $ready) { "TIMEOUT: docker engine did not come up" }

docker pull mcr.microsoft.com/mssql/server:2022-latest 2>&1 | Select-Object -Last 3
docker rm -f relay-tz-check 2>$null | Out-Null
docker run -d --name relay-tz-check -e ACCEPT_EULA=Y -e "MSSQL_SA_PASSWORD=Relay!Local2026" -e MSSQL_PID=Developer -p 11433:1433 mcr.microsoft.com/mssql/server:2022-latest 2>&1 | Select-Object -Last 1
"--- waiting for sqlservr to accept connections ---"
$ok = $false
for ($i = 0; $i -lt 180; $i += 5) {
    $r = docker exec relay-tz-check /opt/mssql-tools18/bin/sqlcmd -S localhost -U sa -P 'Relay!Local2026' -C -No -Q "SELECT 1" 2>&1
    if ($r -match '^\s*1\s*$' -or ($r -join ' ') -match '\b1\b.*rows affected') { $ok = $true; "ready after ~${i}s"; break }
    Start-Sleep -Seconds 5
}
if (-not $ok) { "NOT READY"; docker logs --tail 15 relay-tz-check }

$pulled = $false
for ($a = 1; $a -le 4; $a++) {
    "--- pull attempt $a ---"
    docker pull mcr.microsoft.com/mssql/server:2022-latest 2>&1 | Select-Object -Last 2
    if ((docker images -q mcr.microsoft.com/mssql/server:2022-latest 2>$null)) { $pulled = $true; break }
}
if ($pulled) { docker images --format "{{.Repository}}:{{.Tag}} {{.Size}}" | Select-String mssql } else { "PULL FAILED after 4 attempts" }

docker rm -f relay-tz-check 2>$null | Out-Null
docker run -d --name relay-tz-check -e ACCEPT_EULA=Y -e "MSSQL_SA_PASSWORD=Relay!Local2026" -e MSSQL_PID=Developer -p 11433:1433 mcr.microsoft.com/mssql/server:2022-latest 2>&1 | Select-Object -Last 1
$ok = $false
for ($i = 0; $i -lt 180; $i += 5) {
    $r = (docker exec relay-tz-check /opt/mssql-tools18/bin/sqlcmd -S localhost -U sa -P 'Relay!Local2026' -C -No -Q "SET NOCOUNT ON; SELECT 'PING'" 2>&1) -join ' '
    if ($r -match 'PING') { $ok = $true; "sqlservr ready after ~${i}s"; break }
    Start-Sleep -Seconds 5
}
if (-not $ok) { "NOT READY"; docker logs --tail 20 relay-tz-check }

input.content:
SET NOCOUNT ON;
PRINT '--- 1. engine / platform ---';
SELECT @@VERSION AS v;

PRINT '--- 2. how many zones, and what do the names look like? ---';
SELECT COUNT(*) AS zone_count FROM sys.time_zone_info;
SELECT TOP 5 name FROM sys.time_zone_info ORDER BY name;

PRINT '--- 3. is an IANA name present in sys.time_zone_info? ---';
SELECT name, current_utc_offset, is_currently_dst
FROM sys.time_zone_info
WHERE name IN ('America/Chicago', 'Central Standard Time',
               'America/Phoenix', 'US Mountain Standard Time');

PRINT '--- 4. AT TIME ZONE with a WINDOWS id ---';
BEGIN TRY
    SELECT CAST('2026-06-03 18:00:00' AS datetime2) AT TIME ZONE 'UTC'
           AT TIME ZONE 'Central Standard Time' AS windows_id_result;
END TRY
BEGIN CATCH
    SELECT 'FAILED: ' + ERROR_MESSAGE() AS windows_id_result;
END CATCH

PRINT '--- 5. AT TIME ZONE with an IANA id (the claim under test) ---';
BEGIN TRY
    SELECT CAST('2026-06-03 18:00:00' AS datetime2) AT TIME ZONE 'UTC'
           AT TIME ZONE 'America/Chicago' AS iana_id_result;
END TRY
BEGIN CATCH
    SELECT 'FAILED: ' + ERROR_MESSAGE() AS iana_id_result;
END CATCH

PRINT '--- 6. DST correctness: does it shift across the 2026-03-08 transition? ---';
BEGIN TRY
    SELECT
        CAST('2026-02-15 18:00:00' AS datetime2) AT TIME ZONE 'UTC'
            AT TIME ZONE 'America/Chicago' AS winter_iana,
        CAST('2026-06-15 18:00:00' AS datetime2) AT TIME ZONE 'UTC'
            AT TIME ZONE 'America/Chicago' AS summer_iana;
END TRY
BEGIN CATCH
    SELECT 'FAILED: ' + ERROR_MESSAGE() AS dst_result;
END CATCH

PRINT '--- 7. Phoenix (no DST) via IANA ---';
BEGIN TRY
    SELECT
        CAST('2026-02-15 18:00:00' AS datetime2) AT TIME ZONE 'UTC'
            AT TIME ZONE 'America/Phoenix' AS phoenix_winter,
        CAST('2026-06-15 18:00:00' AS datetime2) AT TIME ZONE 'UTC'
            AT TIME ZONE 'America/Phoenix' AS phoenix_summer;
END TRY
BEGIN CATCH
    SELECT 'FAILED: ' + ERROR_MESSAGE() AS phoenix_result;
END CATCH

PRINT '--- 8. every IANA zone used by the seed accounts ---';
BEGIN TRY
    SELECT z.tz,
           CAST('2026-06-15 18:00:00' AS datetime2) AT TIME ZONE 'UTC' AT TIME ZONE z.tz AS converted
    FROM (VALUES ('America/Chicago'), ('America/New_York'), ('America/Denver'),
                 ('America/Los_Angeles'), ('America/Phoenix'), ('UTC')) AS z(tz);
END TRY
BEGIN CATCH
    SELECT 'FAILED: ' + ERROR_MESSAGE() AS all_zones_result;
END CATCH

